import hashlib
for record in d['records']:
 assert len(record['timeline'])>20 and record['timeline'][0]['elapsed']==0
 files=['../../output/bill-carry-return-east-v1/'+record['name']+'-after-source.png']+['../../output/bill-carry-return-east-v1/'+record['name']+'-return-'+str(v['slot'])+'.png' for v in record['sources']]+['../../output/bill-carry-return-east-v1/'+record['name']+'-end-source.png']
 record['images']=files
 record['fileSha256']={str(file):hashlib.sha256((P/file).read_bytes()).hexdigest() for file in files}
html="""<!doctype html><meta charset="utf-8"><title>Bill carry return</title><style>body{background:#182932;color:#dde8e9;font:16px system-ui;margin:24px}canvas{background:#22343e;border:1px solid #4c626d}img{max-width:100%}label{margin:12px}a{color:#afd7df}</style><h1>Bill — interrupted carry return</h1><p>The crate stays in his hands as he settles the turn or step, then puts it down. Both versions reuse the accepted master art without resizing or regrading individual poses.</p><p>Moving review replays actual sampled source timestamps at a fixed physical pivot. Full-room native captures verify entry and completion; this is not continuous station footage. The package is staged: complete needs, hazards and fresh-load handling are still open. The old save wrapper deliberately rejects it.</p><label>Interrupted phase <select id="phase"><option value="0.3">Turn</option><option value="0.95">First step</option><option value="1.65">Walking</option></select></label><label>Standing height <select id="height"><option>82</option><option>148</option></select></label><button id="play">Pause</button><p id="clock"></p><div style="display:flex;flex-wrap:wrap;gap:12px"><section><h2>Bare</h2><canvas id="bare" width="288" height="288"></canvas></section><section><h2>Helmet</h2><canvas id="helmet" width="288" height="288"></canvas></section></div><h2>Actual room entry and completion</h2><img src="bare-return-endpoints.png"><img src="helmet-return-endpoints.png"><p><a href="../bill-carry-service-loss-v1/">Previous interruption gap</a></p><script>const cases=CASES;let playing=true,elapsed=0,previous=performance.now();const loaded=new Map();for(const c of cases)for(const path of c.images){const a=new Image();a.src=path;loaded.set(path,a)}document.querySelector('#phase').onchange=()=>elapsed=0;document.querySelector('#play').onclick=()=>{playing=!playing;document.querySelector('#play').textContent=playing?'Pause':'Play'};function draw(c,id,t){const canvas=document.querySelector('#'+id),ctx=canvas.getContext('2d');ctx.clearRect(0,0,288,288);let slot=-1;for(const s of c.timeline){if(s.elapsed>t)break;slot=s.slot}let path=t>=c.duration?c.images.at(-1):c.images[slot+1];const a=loaded.get(path);if(!a.complete)return;let scale=Number(document.querySelector('#height').value)/148;let px=a.width===256?128:92,py=a.width===256?224:172;ctx.drawImage(a,144-px*scale,250-py*scale,a.width*scale,a.height*scale)}function tick(now){if(playing)elapsed+=(now-previous)/1000;previous=now;const chosen=cases.filter(c=>String(c.sample)===document.querySelector('#phase').value);let duration=Math.max(...chosen.map(c=>c.duration))+.5;let t=elapsed%duration;for(const c of chosen)draw(c,c.helmet?'helmet':'bare',t);document.querySelector('#clock').textContent=t.toFixed(2)+'s / '+duration.toFixed(2)+'s';requestAnimationFrame(tick)}requestAnimationFrame(tick);</script>"""
(P/'index.html').write_text(html.replace('CASES',json.dumps(d['records'])),encoding='utf-8')
code=json.loads((P/'code-evidence.json').read_text(encoding='utf-8'));after={name:hashlib.sha256((R/name).read_bytes()).hexdigest() for name in code['sha256']}
